using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;
namespace DungeonContract.Editor {
 public static class DcV6Checks {
  private static JObject parameters,geometry,configuration;private static readonly List<string> passed=new List<string>();
  private static void Require(bool v,string m){if(!v)throw new InvalidOperationException(m);}
  private static void Case(string name,Action test){test();passed.Add(name);Debug.Log("V6 CHECK "+name);}
  private static JObject Point(float x,float y)=>new JObject{["x"]=x,["y"]=y};
  private static DcP1World World(string kit="ranger",bool melee=false,bool dense=false,string variant="a",int party=1,long seed=17){
   var g=(JObject)geometry.DeepClone();if(dense)foreach(var room in ((JArray)g["rooms"]).Cast<JObject>()){var selected=((JArray)room["variants"]).FirstOrDefault(v=>((string)v["id"]).EndsWith("_"+variant,StringComparison.Ordinal))??room["variants"][0];foreach(var key in new[]{"obstacles_milli","cover_points_milli","trap_points_milli","covers","traps","spawn_candidates_milli","mandatory_cover_groups"})room[key]=selected[key].DeepClone();room["variant_id"]=selected["id"].DeepClone();}if(!dense)foreach(var room in (JArray)g["rooms"]){room["obstacles_milli"]=new JArray();room["cover_points_milli"]=new JArray();room["trap_points_milli"]=new JArray();room["covers"]=new JArray();room["traps"]=new JArray();}
   var world=new DcP1World(new JObject{["run_id"]="v6_model",["seed"]=seed,["parameters"]=parameters,["p1_world"]=g,["config"]=configuration,["p4_stage"]=true,["p3_stage"]=true,["p2_stage"]=true,["weapon_stage"]=true,["members"]=new JArray(Enumerable.Range(0,party).Select(slot=>new JObject{["player_id"]=(slot+1).ToString(),["slot"]=slot,["loadout_id"]=kit})),["task_requirements"]=new JObject{["1"]=new JObject{["damage:"]=100}}});
   var state=world.Capture();state["players"][0]["Room"]=1;state["players"][0]["Position"]=Point(5,9);state["players"][0]["MeleeEquipped"]=melee;state["rooms"][1]["Status"]="active";state["rooms"][1]["Wave"]=1;state["enemies"]=new JArray(new JObject{["ID"]="foe_1",["Kind"]="guard",["Room"]=1,["Position"]=Point(20,9),["Origin"]=Point(20,9),["Health"]=10000,["Maximum"]=10000,["ReadyAt"]=long.MaxValue});world.Restore(state);return world;
  }
  private static JObject Own(DcP1World w)=>(JObject)w.Snapshot()["players"][0];
  private static DcP1Input Input(DcP1World w,Vector2 move=default,bool held=false){var p=Own(w);return new DcP1Input{WeaponID=(string)p["active_weapon_id"],WeaponRevision=(uint)p["weapon_revision"],Aim=0,Move=move,Melee=held&&(bool)p["melee_equipped"],Attack=held&&!(bool)p["melee_equipped"],AttackEpisode=(string)p["attack_episode_id"],ChargeEpisode=(string)p["charge_episode_id"]};}
  private static void Step(DcP1World w,int ticks,Vector2 move=default,bool held=false){var begin=w.GameTime;for(var i=1;i<=ticks;i++){w.Input("1",Input(w,move,held));w.Tick(begin+(i*1000+29)/30);w.DrainV6Lifecycle();}}
  private static void Change(DcP1World w,Action<JObject> f){var s=w.Capture();f(s);w.Restore(s);}
  private static JObject Bullet(int number=900,bool hostile=true,float x=6,float y=9,float dx=-1,float dy=0,float speed=10,float radius=0.1f)=>new JObject{["ID"]="projectile_"+number.ToString("D6"),["Action"]="projectile_"+number.ToString("D6"),["Root"]="root_"+number,["Owner"]=hostile?"foe_1":"1",["SourceLife"]=1,["Room"]=1,["Position"]=Point(x,y),["Direction"]=Point(dx,dy),["Damage"]=12,["Speed"]=speed,["CollisionRadius"]=radius,["Enemy"]=hostile,["Unbounded"]=true,["NetworkGroup"]=number%43,["Hit"]=new JArray()};
  private static JObject Snapshot(DcP1World w,int frame=10){var s=w.Snapshot();s["protocol_version"]=6;s["state_revision"]=1;s["interest_revision"]=1;s["lifecycle_watermark"]=0;s["world_frame_id"]=frame;return s;}
  private static DcS1Replica Replica(JObject snapshot){var b=(JObject)snapshot.DeepClone();DcS1Replica.PackV6Baseline(b,true);var r=new DcS1Replica();r.Baseline(b,"1",1);return r;}
  private static JObject Event(JObject flight,int seq,string kind="spawn")=>new JObject{["event_id"]="case_"+seq,["kind"]=kind,["entity_id"]=flight["id"],["room_id"]=flight["room_id"],["frame"]=11,["game_ms"]=367,["subtick"]=0,["trajectory_revision"]=0,["reason"]=kind=="terminate"?"wall":null,["state"]=flight.DeepClone(),["delivery_sequence"]=seq};
  private static JObject Batch(params JObject[] events)=>new JObject{["interest_revision"]=1,["events"]=new JArray(events)};
  public static void Regression(){DcV5Checks.Regression();DcP5Checks.Run();}
  public static void Run(){
   parameters=JObject.Parse(File.ReadAllText("../../docs/game-demo/config/parameters-v6-p5.json"));geometry=JObject.Parse(File.ReadAllText("../../docs/game-demo/config/world-v6-p5.json"));configuration=JObject.Parse(File.ReadAllText("../../docs/game-demo/config/demo-v6-p5.json"));passed.Clear();
   Case("v6 independent identity and complete P3 P4 systems",()=>{var w=World();Require(w.V6&&w.V5&&w.P3&&w.P4,"stage");Require((int)Own(w)["movement_profile"]["speed"]==7,"profile");});
   Case("seven tiles per second authoritative movement",()=>{var w=World();Step(w,30,Vector2.right);Require(Math.Abs((float)Own(w)["x"]-12)<0.002f,"walk speed");});
   Case("diagonal movement normalized",()=>{var w=World();Step(w,15,new Vector2(1,1));Require(Math.Abs(Vector2.Distance(new Vector2(5,9),new Vector2((float)Own(w)["x"],(float)Own(w)["y"]))-3.5f)<0.002f,"diagonal boost");});
   Case("long Space locks direction with exact distance",()=>{var w=World();var input=Input(w,Vector2.right);Require(w.Action("1","dodge",input),"dodge");Step(w,17,Vector2.up);var p=Own(w);Require((float)p["x"]>12.5f&&Math.Abs((float)p["y"]-9)<0.01f,"lock or speed");Require((long)p["dodge_remaining_ms"]>2000,"CD");});
   Case("wall collision ends only dash protection",()=>{var w=World();Change(w,s=>{s["players"][0]["Position"]=Point(28.2f,9);s["players"][0]["HurtUntil"]=500;s["players"][0]["ProtectedUntil"]=200;s["players"][0]["RescueUntil"]=200;});Require(w.Action("1","dodge",Input(w,Vector2.right)),"space");Step(w,3,Vector2.right);var p=Own(w);Require((long)p["dodge_duration_remaining_ms"]==0&&(long)p["protection_sources"]["space"]<200&&(long)p["protection_sources"]["hurt"]==500&&(long)p["protection_sources"]["rescue"]==200,"source cancellation");Require((float)p["x"]<=28.761f,"wall tunnelling");});
   Case("ordinary body pass and elite blocking",()=>{foreach(var kind in new[]{"guard","elite","boss"}){var w=World();Change(w,s=>{s["enemies"][0]["Kind"]=kind;s["enemies"][0]["Position"]=Point(7,9);});w.Action("1","dodge",Input(w,Vector2.right));Step(w,12,Vector2.right);Require(kind=="guard"?(float)Own(w)["x"]>9:(float)Own(w)["x"]<7,"blocking "+kind);}});
   Case("first Space uses current aim without movement history",()=>{var w=World();var input=Input(w);input.Aim=16384;w.Action("1","dodge",input);Step(w,1);Require((float)Own(w)["y"]>9.4f,"initial right default");});
   Case("volley four-tile profile and independent Space",()=>{var w=World();w.Action("1","ability_primary",Input(w));Require((long)Own(w)["dodge_duration_remaining_ms"]==300&&(long)Own(w)["dodge_remaining_ms"]==0,"gust profile");Step(w,8);Require((float)Own(w)["x"]>8.5f,"gust distance");});
   Case("volley during Space does not extend its invulnerability",()=>{var w=World();w.Action("1","dodge",Input(w,Vector2.right));var until=(long)Own(w)["protection_sources"]["space"];w.Action("1","ability_primary",Input(w));Require((long)Own(w)["protection_sources"]["space"]==until&&(long)Own(w)["protection_sources"]["gust"]==0,"dash refreshed");});
   Case("open door accepts aligned outward intent after lateral plane overshoot",()=>{var w=World();Change(w,state=>{state["players"][0]["Room"]=9;state["players"][0]["Position"]=Point(4.76f,2.8f);});Step(w,1,Vector2.right);Require((int)Own(w)["room_id"]==2,"door edge softlock");});
   Case("long dash ends at open transition without carried distance or immunity",()=>{var w=World();Change(w,state=>{state["players"][0]["Room"]=9;state["players"][0]["Position"]=Point(4.3f,2.5f);});w.Action("1","dodge",Input(w,Vector2.right));Step(w,1,Vector2.right);var p=Own(w);Require((int)p["room_id"]==2&&Math.Abs((float)p["x"]-2.1f)<0.01f&&(long)p["dodge_duration_remaining_ms"]==0&&(long)p["protection_sources"]["space"]<=34,"dash crossed with resources");});
   Case("all fixed weapon IDs resolve existing artwork without asset edits",()=>{foreach(var kit in parameters["loadouts"])foreach(var slot in new[]{"ranged","melee"})Require(DcP5Art.Weapon((string)kit[slot]["weapon"])!=null,"unmapped weapon "+kit[slot]["weapon"]);});
   Case("held fire cannot emit a new projectile inside connector",()=>{var w=World();Change(w,state=>{state["players"][0]["Room"]=9;state["players"][0]["Position"]=Point(3,2.5f);state["players"][0]["AttackEpisode"]="held_1";});Step(w,3,held:true);Require(!w.Capture()["projectiles"].Any(),"connector emission");});
   Case("melee ranges arcs and unchanged total cycles",()=>{foreach(var kit in new[]{"ranger","runesmith"}){var w=World(kit,true);w.Action("1","attack_press",Input(w));Step(w,kit=="ranger"?2:6);var a=Own(w)["melee_action"];Require((float)a["range"]==(kit=="ranger"?2:2.6f)&&(int)a["arc"]==(kit=="ranger"?240:270),"shape");Require((long)a["end_tick"]-(long)a["started_tick"]==(kit=="ranger"?9:21),"cycle changed");}});
   Case("current rotating sweep catches crossing and excludes trailing sector",()=>{var hit=DcV6Geometry.Sweep(Vector2.zero,Vector2.zero,Vector2.right,-120,-40,2,new Vector2(0,-2),new Vector2(0,-1),0.1f);Require(hit.HasValue,"crossing missed");Require(!DcV6Geometry.Sweep(Vector2.zero,Vector2.zero,Vector2.right,40,120,2,new Vector2(0,-1),new Vector2(0,-1),0.1f).HasValue,"old swept area shield");});
   Case("back sector larger than 180 respects current band",()=>{Require(DcV6Geometry.Sweep(Vector2.zero,Vector2.zero,Vector2.right,90,135,2.6f,new Vector2(-1,2),new Vector2(-1,2),0.2f).HasValue,"rear wedge missed");Require(!DcV6Geometry.Sweep(Vector2.zero,Vector2.zero,Vector2.right,90,135,2.6f,Vector2.right,Vector2.right,0.1f).HasValue,"full sector shield");});
   Case("hammer windup preview never defaults to world origin",()=>{var w=World("runesmith",true);w.Action("1","charge_begin",Input(w));w.AdvanceTime(900);var input=Input(w);input.PressActionID=(string)Own(w)["charge_episode_id"];w.Action("1","charge_release",input);var a=Own(w)["melee_action"];Require((bool)a["preview_valid"]&&!(bool)a["impact_valid"]&&(float)a["preview_x"]>5,"uninitialized preview");});
   Case("charged hammer direct remains exact 2D",()=>{var w=World("runesmith",true);Change(w,s=>s["enemies"][0]["Position"]=Point(6.5f,9));w.Action("1","charge_begin",Input(w));w.AdvanceTime(900);var input=Input(w);input.PressActionID=(string)Own(w)["charge_episode_id"];w.Action("1","charge_release",input);Step(w,7);Require((int)w.Capture()["enemies"][0]["Health"]==9872,"slam changed");});
   Case("actual reload duration is frozen across later growth",()=>{var w=World();Change(w,s=>s["players"][0]["Magazine"]=1);w.Action("1","reload",Input(w));var own=Own(w);Require((int)own["reload_duration_ms"]==900,"initial reload");Change(w,s=>s["players"][0]["Upgrades"]=new JArray("ranger_tension"));Require((int)Own(w)["reload_duration_ms"]==900,"retroactive reload changed");});
   Case("large rune and turret share 0.72 radius",()=>{var w=World("runesmith");w.Action("1","attack_press",Input(w));Step(w,1);Require(w.Capture()["projectiles"].All(p=>(float)p["CollisionRadius"]==0.72f),"rune size");Require((int)parameters["loadouts"][1]["primary"]["projectile_radius_milli_tiles"]==720,"turret spec");});
   Case("friendly first muzzle segment cannot skip close enemy",()=>{var w=World("runesmith");Change(w,s=>s["enemies"][0]["Position"]=Point(5.6f,9));w.Action("1","attack_press",Input(w));Step(w,1);Require((int)w.Capture()["enemies"][0]["Health"]==9984,"muzzle skipped hit");});
   Case("one bounce records contact and cannot reset bounce budget",()=>{var w=World("runesmith");Change(w,s=>{var b=Bullet(hostile:false,x:27.9f,dx:1,speed:20,radius:0.72f);b["RuneBolt"]=true;b["Bounces"]=1;s["projectiles"]=new JArray(b);});w.Tick(34);var ev=w.DrainV6Lifecycle();Require(ev.Count(e=>(string)e["kind"]=="bounce")==1,"bounce missing");Require((int)w.Capture()["projectiles"][0]["Bounces"]==0,"refund");});
   Case("blocked projectile terminates at contact rather than endpoint",()=>{var w=World();Change(w,s=>s["projectiles"]=new JArray(Bullet(x:28.7f,dx:1,speed:30)));w.Tick(34);var ev=w.DrainV6Lifecycle();Require(ev.Any(e=>(string)e["kind"]=="terminate"&&(string)e["reason"]=="wall")&&!w.Capture()["projectiles"].Any(),"wall termination");});
   Case("same-tick projectile birth and death both have reliable evidence",()=>{var w=World("runesmith");Change(w,s=>s["enemies"][0]["Position"]=Point(5.5f,9));w.Action("1","attack_press",Input(w));w.Tick(34);var ev=w.DrainV6Lifecycle();Require(ev.Count(e=>(string)e["kind"]=="spawn")==1&&ev.Count(e=>(string)e["kind"]=="terminate")==1,"short life lost");});
   Case("field carries owner life cast and actual expiry",()=>{var w=World();w.Action("1","ability_secondary",Input(w));var f=w.Snapshot()["fields"][0];Require((string)f["owner"]=="1"&&(long)f["owner_life"]==1&&(long)f["ends_ms"]==2000,"attachment identity");});
   Case("dense rooms instantiate selected covers and traps only",()=>{var w=World(dense:true);var s=w.Capture();Require(((JArray)s["covers"]).Count==584&&((JArray)s["traps"]).Count==114,"counts");Require(((JArray)geometry["rooms"]).Count==15,"zones");});
   Case("ABC cycles start once and technically restart with full warning",()=>{var w=World(dense:true);w.Tick(34);var traps=(JArray)w.Snapshot()["traps"];var first=traps.First(t=>(int)t["room_id"]==1);Require((long)first["activation_epoch_ms"]==34,"activation");var epoch=(long)first["activation_epoch_ms"];w.Tick(634);Require((string)w.Snapshot()["traps"].First(t=>(string)t["id"]==(string)first["id"])["phase"]=="active","phase boundary");w.TechnicalWait(true,634);w.TechnicalWait(false,9634);w.Tick(9667);var current=w.Snapshot()["traps"].First(t=>(string)t["id"]==(string)first["id"]);Require((int)current["activation_generation"]==2&&(long)current["activation_epoch_ms"]==9634&&(string)current["phase"]!="active","resume catchup damage");});
   Case("terrain continuous cast catches thin walls and reflection normal",()=>{var room=new JObject{["width"]=34,["height"]=20,["obstacles"]=new JArray((object)new JArray(6,5,0.05,8))};var h=DcV6Geometry.Terrain(room,new Vector2(5,9),new Vector2(9,9),0.24f);Require(h.HasValue&&h.Value.Time<0.2f&&h.Value.Normal.x<0,"thin wall");});
   Case("round projectile corner graze uses circle not expanded square",()=>{Require(!DcV6Geometry.Box(new Vector2(4,4.4f),new Vector2(4.4f,4.4f),5,5,1,1,0.72f).HasValue,"false square collision");var contact=DcV6Geometry.Box(new Vector2(4,4.6f),new Vector2(6,4.6f),5,5,1,1,0.72f);Require(contact.HasValue&&contact.Value.Normal.x<0&&contact.Value.Normal.y<0,"rounded normal");});
   Case("rounded terrain casts agree with an independent sampled distance oracle",()=>{var random=new System.Random(23);for(var i=0;i<256;i++){var a=new Vector2(3+(float)random.NextDouble()*6,3+(float)random.NextDouble()*6);var b=new Vector2(3+(float)random.NextDouble()*6,3+(float)random.NextDouble()*6);var radius=i%2==0?0.24f:0.72f;Func<float,float> squared=t=>{var p=Vector2.Lerp(a,b,t);return (p-new Vector2(Mathf.Clamp(p.x,5,6),Mathf.Clamp(p.y,5,6))).sqrMagnitude;};var contact=DcV6Geometry.Box(a,b,5,5,1,1,radius);if(contact.HasValue){Require(contact.Value.Time>=0&&contact.Value.Time<=1&&squared(contact.Value.Time)<=radius*radius+0.0001f,"invalid rounded contact");for(var step=0;step<1000&&step/1000f<contact.Value.Time-0.002f;step++)Require(squared(step/1000f)>=radius*radius-0.0001f,"missed earlier rounded contact");}else for(var step=0;step<=1000;step++)Require(squared(step/1000f)>=radius*radius-0.0001f,"missed rounded intersection");}var layout=new JObject{["width"]=12,["height"]=12,["v6_geometry"]=true,["obstacles"]=new JArray((object)new JArray(5.31,5,0.01,2))};Require(!RoomGeometry.ClearLine(layout,new Vector2(4,6),new Vector2(7,6)),"continuous sight skipped thin terrain");});
   Case("same-frame hurt protection starts at earliest hostile contact",()=>{var w=World();Change(w,state=>{var late=Bullet(901,x:5.9f,speed:20);late["Damage"]=30;var early=Bullet(902,x:5.5f,speed:20);early["Damage"]=10;state["projectiles"]=new JArray(late,early);});Step(w,1);Require((int)Own(w)["health"]==90,"creation order overrode contact time");});
   Case("navigation direct shortcut uses body radius not thin sight",()=>{var layout=new JObject{["width"]=12,["height"]=12,["v6_geometry"]=true,["obstacles"]=new JArray((object)new JArray(5,5,1,1))};var start=new Vector2(3.5f,4.6f);var goal=new Vector2(8.5f,4.6f);Require(RoomGeometry.ClearLine(layout,start,goal),"thin sight setup");var direction=RoomGeometry.PathDirection(layout,start,goal,0.6f);Require(direction.sqrMagnitude>0&&Math.Abs(direction.y)>0.05f,"walked directly into body obstruction");});
   Case("both dense mechanism variants route guard into opened hub without teleport",()=>{foreach(var variant in new[]{"a","b"}){var w=World(dense:true,variant:variant);Change(w,state=>{state["players"][0]["Room"]=2;state["players"][0]["Position"]=Point(22,10);state["players"][0]["ProtectedUntil"]=long.MaxValue;state["rooms"][1]["Status"]="unvisited";state["rooms"][2]["Status"]="active";state["rooms"][2]["Wave"]=3;state["enemies"][0]["Room"]=2;state["enemies"][0]["Position"]=Point(6.5f,9.5f);state["enemies"][0]["ReadyAt"]=0;foreach(var cover in state["covers"])if((int)cover["Room"]==2&&Math.Abs((float)cover["Position"]["x"]-18.5f)<0.01f&&((float)cover["Position"]["y"]==9.5f||(float)cover["Position"]["y"]==10.5f))cover["Health"]=0;});Step(w,600);var e=w.Capture()["enemies"].FirstOrDefault(v=>(string)v["ID"]=="foe_1");Require(!w.Terminal&&e!=null&&Vector2.Distance(new Vector2((float)e["Position"]["x"],(float)e["Position"]["y"]),new Vector2(22,10))<3&&(int)e["RecoveryCount"]==0,"dense body path stalled "+variant);}});
   Case("delivery sequence allocated after interest filtering",()=>{var stream=new DcV6LifecycleStream();stream.ResetRoom(1);var w=World();Change(w,s=>s["projectiles"]=new JArray(Bullet()));var flight=(JObject)Snapshot(w)["projectiles"][0];var e=Event(flight,1);e["room_id"]=5;Require(stream.Add(e)&&stream.Sequence==0,"room gap");e["room_id"]=1;Require(stream.Add(e)&&stream.Sequence==1,"visible sequence");});
   Case("lifecycle batches respect both count and bytes",()=>{var w=World();Change(w,s=>s["projectiles"]=new JArray(Bullet()));var f=(JObject)Snapshot(w)["projectiles"][0];var stream=new DcV6LifecycleStream();stream.ResetRoom(1);for(var i=0;i<140;i++)Require(stream.Add(Event(f,i+1)),"enqueue");var batches=stream.Batches();Require(batches.Length>=3&&batches.All(b=>((JArray)b["events"]).Count<=64&&System.Text.Encoding.UTF8.GetByteCount(b.ToString(Newtonsoft.Json.Formatting.None))<=15500),"batch cap");});
   Case("unknown dynamic never creates true projectile",()=>{var w=World();var empty=Snapshot(w);var replica=Replica(empty);Change(w,s=>s["projectiles"]=new JArray(Bullet()));var full=Snapshot(w,11);foreach(var p in DcS1Replica.EncodeV6(full,1,7,9,"1",1,1,h=>1))replica.Dynamic(p,7,9);Require(!((JArray)replica.Snapshot["projectiles"]).Any()&&replica.V6UnknownCount==1,"unknown was spawned");});
   Case("reliable spawn unlocks buffered dynamic without deleting omitted rows",()=>{var w=World();var replica=Replica(Snapshot(w));Change(w,s=>s["projectiles"]=new JArray(Bullet()));var s=Snapshot(w,11);var flight=(JObject)s["projectiles"][0];foreach(var p in DcS1Replica.EncodeV6(s,1,7,9,"1",1,1,h=>1))replica.Dynamic(p,7,9);Require(replica.ApplyV6Lifecycle(Batch(Event(flight,1)))&&((JArray)replica.Snapshot["projectiles"]).Count==1,"reliable birth");var zero=Snapshot(World(),12);foreach(var p in DcS1Replica.EncodeV6(zero,1,7,9,"1",1,1))replica.Dynamic(p,7,9);Require(((JArray)replica.Snapshot["projectiles"]).Count==1,"missing row deleted flight");});
   Case("reliable termination immediate and old dynamic cannot resurrect",()=>{var w=World();var replica=Replica(Snapshot(w));Change(w,s=>s["projectiles"]=new JArray(Bullet()));var s=Snapshot(w,11);var flight=(JObject)s["projectiles"][0];replica.ApplyV6Lifecycle(Batch(Event(flight,1),Event(flight,2,"terminate")));foreach(var p in DcS1Replica.EncodeV6(s,1,7,9,"1",1,2,h=>1))replica.Dynamic(p,7,9);Require(!((JArray)replica.Snapshot["projectiles"]).Any()&&replica.V6TombstoneCount==1,"resurrection");replica.ApplyV6Lifecycle(Batch(Event(flight,1)));Require(!((JArray)replica.Snapshot["projectiles"]).Any(),"old spawn");});
